// ─── Máquina de Estados del Gimnasio (WhatsApp + Telegram) ──────────────────

const BRIDGE_URL = 'http://host.docker.internal:3003';
const BRIDGE_KEY = 'cambia-esta-clave-secreta';
const bridgeHeaders = { 'x-bridge-api-key': BRIDGE_KEY };

const inputJson = $input.first().json;
const body = inputJson.body || inputJson;

let canal = 'whatsapp';
let desde = '';
let texto = '';

// Detección automática del canal (Telegram vs WhatsApp)
if (body.message && body.message.chat) {
  canal = 'telegram';
  desde = String(body.message.chat.id);
  texto = (body.message.text || '').trim();
} else if (body.canal === 'telegram' || (body.chatId && !body.desde)) {
  canal = 'telegram';
  desde = String(body.chatId || body.desde || '');
  texto = String(body.texto || body.mensaje || '').trim();
} else if (body.desde && body.texto) {
  canal = body.canal || 'whatsapp';
  desde = body.desde;
  texto = body.texto.trim();
} else {
  const messages = body.messages || [];
  if (!messages.length) return [{ json: { ignorar: true } }];
  const msg = messages[0];
  const deMi = msg.from_me ?? msg.fromMe ?? false;
  if (deMi || msg.type !== 'text') return [{ json: { ignorar: true } }];
  desde = msg.chat_id || msg.chatId || msg.from || '';
  texto = (msg.text?.body || msg.body || '').trim();
}

const claveEstado = canal === 'telegram' ? `tg-${desde}` : desde.replace('@s.whatsapp.net', '').replace('@c.us', '');
if (!texto || !desde) return [{ json: { ignorar: true } }];

const textoLower = texto.toLowerCase();

// Obtener estado actual de conversación
let estadoActual = { estado: 'MENU', datos: {} };
try {
  const resp = await $http.get(`${BRIDGE_URL}/estado/${claveEstado}`, { headers: bridgeHeaders });
  if (resp && resp.estado) estadoActual = resp;
} catch (e) {}

// Comandos globales de reinicio
if (['menu', 'inicio', 'hola', 'buenas', 'hi', 'start', '/start', 'reiniciar', 'cancelar'].includes(textoLower)) {
  try { await $http.delete(`${BRIDGE_URL}/estado/${claveEstado}`, { headers: bridgeHeaders }); } catch (e) {}
  estadoActual = { estado: 'MENU', datos: {} };
}

let respuesta = '';
let nuevoEstado = estadoActual.estado;
let nuevosDatos = { ...(estadoActual.datos || {}) };
let emailDatos = null;
let limpiarEstado = false;

// ─── Lógica de Navegación del Gimnasio ──────────────────────────────────────
if (textoLower === 'estado' || textoLower === 'mi plan' || textoLower === 'membresia') {
  respuesta = `📋 *Consulta de Estado de Membresía — Titan Gym*\nPor favor envíame tu número de *Carnet de Identidad (CI)*:`;
  nuevoEstado = 'ESPERANDO_CI';
} else if (textoLower === 'renovar' || textoLower === 'planes') {
  respuesta = `💳 *Planes de Membresía Titan Gym*\n\n*1)* Plan Mensual — *Bs. 250* (30 días)\n*2)* Plan Trimestral Black — *Bs. 650* (90 días - Ahorras 13%)\n*3)* Plan Anual VIP — *Bs. 2.200* (365 días + Sauna + 2 Invitados)\n\nResponde con el número (*1, 2 o 3*) del plan que deseas renovar:`;
  nuevoEstado = 'SELECCION_PLAN';
} else if (textoLower === 'promociones' || textoLower === 'promos') {
  respuesta = `🔥 *Promociones del Mes en Titan Gym*\n\n💥 *2x1 Amigos:* Inscríbete con un amigo y el segundo paga la mitad.\n⚡ *Renovación Anticipada:* 15% de descuento antes de tu fecha de vencimiento.\n\n_Escribe *Renovar* para aprovechar estas promociones o *Menu* para volver._`;
} else {
  switch (estadoActual.estado) {
    case 'MENU': {
      if (texto === '1') {
        respuesta = `📋 *Consulta de Membresía*\nIngresa tu número de *Carnet de Identidad (CI)*:`;
        nuevoEstado = 'ESPERANDO_CI';
      } else if (texto === '2') {
        respuesta = `💳 *Planes de Membresía Titan Gym*\n\n*1)* Plan Mensual — *Bs. 250*\n*2)* Plan Trimestral Black — *Bs. 650*\n*3)* Plan Anual VIP — *Bs. 2.200*\n\nResponde con *1, 2 o 3* para elegir:`;
        nuevoEstado = 'SELECCION_PLAN';
      } else if (texto === '3') {
        respuesta = `🔥 *Promociones Vigentes*\n• 15% de descuento renovando antes del vencimiento.\n• Plan Anual con acceso a Sauna y pases gratis.\n\nEscribe *Renovar* para elegir tu membresía.`;
      } else if (texto === '4') {
        respuesta = `📍 *Titan Gym & Fitness*\nAv. Principal #1024, Edif. Spartan, Piso 2.\n⏰ Lun-Vie: 06:00 a 22:00 | Sáb: 08:00 a 18:00.`;
      } else if (/^\d{5,9}$/.test(texto)) {
        respuesta = `📋 *Estado de Membresía — Titan Gym*\n\n👤 *Socio:* Juan Pérez\n🪪 *CI:* ${texto}\n🏋️‍♂️ *Plan:* Plan Trimestral Black\n📅 *Vence:* 31 de Octubre de 2026\n⏳ *Días Restantes:* 12 días 🟢\n\n¿Deseas renovar tu plan?\n👉 Escribe *Renovar* o escribe *Menu* para volver.`;
        limpiarEstado = true;
      } else {
        respuesta = `🏋️‍♂️ *¡Bienvenido a Titan Gym & Fitness!* 🥊\n\n¿En qué podemos ayudarte?\n*1)* 📋 Consultar Estado de Membresía\n*2)* 💳 Renovar Membresía\n*3)* 🔥 Promociones del Mes\n*4)* ⏰ Horarios y Ubicación\n\n_Elige una opción (1-4) o escribe tu *CI*:_`;
        nuevoEstado = 'MENU';
      }
      break;
    }

    case 'ESPERANDO_CI': {
      const ci = texto.replace(/[^0-9]/g, '');
      respuesta = `📋 *Estado de Membresía — Titan Gym*\n\n👤 *Socio:* Juan Pérez\n🪪 *CI:* ${ci || texto}\n🏋️‍♂️ *Plan Actual:* Plan Trimestral Black\n📅 *Fecha de Vencimiento:* 31 de Octubre de 2026\n⏳ *Días Restantes:* 12 días 🟢\n✨ Acceso a tornos biométricos habilitado.\n\n¿Deseas renovar tu membresía?\n👉 Escribe *Renovar*\n👉 Escribe *Menu* para volver`;
      limpiarEstado = true;
      break;
    }

    case 'SELECCION_PLAN': {
      const planes = {
        '1': { nombre: 'Plan Mensual Estándar', dias: 30, precio: 250 },
        '2': { nombre: 'Plan Trimestral Black', dias: 90, precio: 650 },
        '3': { nombre: 'Plan Anual VIP', dias: 365, precio: 2200 }
      };
      const planElegido = planes[texto];
      if (!planElegido) {
        respuesta = `Por favor responde con una opción válida (*1, 2 o 3*):`;
      } else {
        nuevosDatos.plan = planElegido;
        respuesta = `🧾 *Confirmación de Renovación*\n\n🏋️‍♂️ *Plan:* ${planElegido.nombre}\n💵 *Monto:* Bs. ${planElegido.precio}\n⏳ *Vigencia:* ${planElegido.dias} días\n\nResponde *SI* para confirmar la activación inmediata o *Cancelar*:`;
        nuevoEstado = 'CONFIRMAR_RENOVACION';
      }
      break;
    }

    case 'CONFIRMAR_RENOVACION': {
      if (['si', 'sí', 'ok', 'confirmar'].includes(textoLower)) {
        const p = nuevosDatos.plan || { nombre: 'Plan Mensual', precio: 250, dias: 30 };
        const hoy = new Date();
        hoy.setDate(hoy.getDate() + p.dias);
        const fVenc = hoy.toLocaleDateString('es-BO', { day: '2-digit', month: 'long', year: 'numeric' });

        respuesta = `🎉 *¡Membresía Renovada con Éxito!* 🏋️‍♂️\n\n⭐ *Plan:* ${p.nombre}\n📅 *Nueva Fecha de Vencimiento:* ${fVenc}\n✅ Acceso por torno y App móvil habilitados.\n\n¡A darlo todo en el entrenamiento! 💪🔥`;

        emailDatos = {
          para: 'juan.perez@gmail.com',
          asunto: `Confirmación de Membresía — ${p.nombre}`,
          nombre: 'Juan Pérez',
          tipo: 'CONFIRMACION_RENOVACION',
          plan: p.nombre,
          fechaVencimiento: fVenc,
          monto: `Bs. ${p.precio}`,
          diasRestantes: p.dias
        };
        limpiarEstado = true;
      } else {
        respuesta = `Renovación cancelada. Escribe *Menu* cuando desees volver.`;
        limpiarEstado = true;
      }
      break;
    }

    default: {
      respuesta = `Escribe *Menu* para ver las opciones disponibles en Titan Gym.`;
      limpiarEstado = true;
      break;
    }
  }
}

// Actualizar o limpiar estado en Bridge MS
if (limpiarEstado) {
  try { await $http.delete(`${BRIDGE_URL}/estado/${claveEstado}`, { headers: bridgeHeaders }); } catch (e) {}
} else {
  try {
    await $http.put(`${BRIDGE_URL}/estado/${claveEstado}`, {
      headers: { ...bridgeHeaders, 'Content-Type': 'application/json' },
      body: { estado: nuevoEstado, datos: nuevosDatos }
    });
  } catch (e) {}
}

return [{
  json: {
    canal,
    esWhatsApp: canal === 'whatsapp',
    esTelegram: canal === 'telegram',
    waDestino: canal === 'whatsapp' ? desde : null,
    waMensaje: respuesta,
    telegramChatId: canal === 'telegram' ? desde : null,
    telegramMensaje: respuesta,
    emailDatos,
    ignorar: !respuesta
  }
}];

// ─── Verificar Socios Próximos a Vencer (Notificaciones Proactivas) ─────────

const sociosPorVencer = [
  {
    nombre: 'Carlos Mendoza',
    telefono: '59178945612@s.whatsapp.net',
    telegramChatId: '123456789',
    email: 'carlos.mendoza@gmail.com',
    plan: 'Plan Mensual Estándar',
    diasRestantes: 2,
    fechaVencimiento: '21 de Octubre de 2026'
  },
  {
    nombre: 'Ana Laura Gómez',
    telefono: '59176543210@s.whatsapp.net',
    telegramChatId: '987654321',
    email: 'ana.gomez@gmail.com',
    plan: 'Plan Trimestral Black',
    diasRestantes: 0,
    fechaVencimiento: 'Hoy'
  }
];

const items = sociosPorVencer.map(socio => {
  const mensaje = socio.diasRestantes > 0
    ? `⚠️ *Titan Gym - Recordatorio de Vencimiento* ⏳\n\nHola *${socio.nombre}*, tu membresía *${socio.plan}* vencerá en *${socio.diasRestantes} días* (${socio.fechaVencimiento}).\n\nEvita interrupciones en tu acceso al gimnasio.\n👉 Responde *Renovar* para extender tu plan ahora mismo.`
    : `🚨 *Titan Gym - Tu membresía vence HOY* 🚨\n\nHola *${socio.nombre}*, tu membresía finaliza el día de hoy.\nA partir de mañana tu acceso por torno se suspenderá temporalmente.\n\n👉 Responde *Renovar* para reactivarla de inmediato.`;

  const emailDatos = {
    para: socio.email,
    asunto: `⚠️ Aviso de Vencimiento de Membresía — Titan Gym`,
    nombre: socio.nombre,
    tipo: 'AVISO_VENCIMIENTO',
    plan: socio.plan,
    fechaVencimiento: socio.fechaVencimiento,
    diasRestantes: socio.diasRestantes,
    mensaje: `Tu membresía está próxima a vencer. Renueva hoy mismo para seguir entrenando sin pausas.`
  };

  return {
    json: {
      waDestino: socio.telefono,
      waMensaje: mensaje,
      telegramChatId: socio.telegramChatId,
      telegramMensaje: mensaje,
      emailDatos,
      ignorar: false
    }
  };
});

return items;

// ─── Broadcast Masivo de Promociones a Socios ───────────────────────────────

const body = $input.first().json.body || $input.first().json;
const promoTitulo = body.titulo || 'Super Descuento de Fin de Mes';
const promoTexto = body.descripcion || 'Obtén 20% de descuento en tu renovación anual o 1 mes gratis por cada amigo referido.';

const listaSocios = [
  { nombre: 'Juan Pérez', telefono: '59170123456@s.whatsapp.net', telegramChatId: '123456789', email: 'juan.perez@gmail.com' },
  { nombre: 'Carlos Mendoza', telefono: '59178945612@s.whatsapp.net', telegramChatId: '987654321', email: 'carlos.mendoza@gmail.com' }
];

const mensaje = `🔥 *Titan Gym - ¡Promoción Especial para Ti!* 🔥\n\nHola amigo socio, tenemos una oferta imperdible:\n\n⭐ *${promoTitulo}*\n${promoTexto}\n\n👉 Responde *Renovar* o escríbenos a recepción para hacer válida esta promo. ¡Te esperamos! 💪`;

return listaSocios.map(socio => ({
  json: {
    waDestino: socio.telefono,
    waMensaje: mensaje,
    telegramChatId: socio.telegramChatId,
    telegramMensaje: mensaje,
    emailDatos: {
      para: socio.email,
      asunto: `🔥 ¡Oferta Especial en Titan Gym!`,
      nombre: socio.nombre,
      tipo: 'PROMOCION',
      mensaje: `${promoTitulo}: ${promoTexto}`
    },
    ignorar: false
  }
}));
